contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address[] memory tos, uint v) public payable {
        bool reverted;
        bool ret;
        if (tos.length == 0) {
            try c.transfer(from, token, tos, v) returns (bool r) { reverted = false; ret = r; }
            catch { reverted = true; ret = false; }
            assert(reverted);
        } else {
            bool ok;
            try c.transfer(from, token, tos, v) returns (bool r) { ok = true; ret = r; }
            catch { ok = false; ret = false; }
            if (ok) { assert(ret); } else { assert(!ret); }
        }
    }
    receive() external payable {}
}

