contract InvMutTest {
    C c;
    uint public calls;
    constructor(C _c) { c = _c; }
    function run(address from, uint v) public payable {
        require(v < 2**128);
        address[] memory tos = new address[](3);
        tos[0] = address(0x11);
        tos[1] = address(0x22);
        tos[2] = address(0x33);
        uint before = calls;
        bool ret = c.transfer(from, address(this), tos, v);
        assert(ret == true && calls - before == tos.length);
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (bytes4(msg.data) == id) {
            calls++;
            return abi.encode(true);
        }
        return new bytes(0);
    }
    receive() external payable {}
}

